<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/domains-fixture.php';
use Hostider\Core\Database\Migrator;
$root=dirname(__DIR__);$db=isolatedDomainDb();$proof=['environment'=>'test','provider_io'=>false,'php'=>PHP_VERSION,'mariadb'=>$db->execute('SELECT VERSION()')->fetchColumn(),'cases'=>[]];
test('F5-A empty MariaDB 001 to 049 replay and all checksums',function()use($db,$root,&$proof): void{$m=new Migrator($db,$root.'/migrations');same(54,count($m->migrate()));same([],$m->migrate());$m->assertReady();$history=$db->execute('SELECT version,checksum,status FROM schema_migrations ORDER BY version')->fetchAll();same(54,count($history));foreach($history as $r){same('APPLIED',$r['status']);same(hash_file('sha256',$root.'/migrations/'.$r['version']),$r['checksum']);}$proof['cases']['empty']=['count'=>54,'replay'=>[],'history'=>$history];});
test('F5-A installed 001 to 048 upgrade only 049 preserve old bytes replay no-op',function()use($root,&$proof): void{$db=isolatedDomainDb();$dir=$root.'/storage/f5-prefix-'.bin2hex(random_bytes(6));mkdir($dir,0700);$files=[];try{foreach(glob($root.'/migrations/*.php') as $p){if(basename($p)<'049'){$to=$dir.'/'.basename($p);copy($p,$to);$files[]=$to;}}same(48,count((new Migrator($db,$dir))->migrate()));$old=$db->execute('SELECT version,checksum,status FROM schema_migrations ORDER BY version')->fetchAll();$m=new Migrator($db,$root.'/migrations');same(['049_support_core.php','050_support_sla_assignment.php','051_support_sla_availability.php','052_support_mail.php','053_support_automation_incident_csat.php','054_support_ui_state.php'],$m->migrate());same([],$m->migrate());$m->assertReady();same($old,$db->execute("SELECT version,checksum,status FROM schema_migrations WHERE version<'049' ORDER BY version")->fetchAll());$proof['cases']['upgrade48']=['prefix'=>48,'applied'=>['049_support_core.php','050_support_sla_assignment.php','051_support_sla_availability.php','052_support_mail.php','053_support_automation_incident_csat.php','054_support_ui_state.php'],'replay'=>[],'old_checksums_unchanged'=>true];}finally{foreach($files as $p){unlink($p);}rmdir($dir);}});
test('F5-A failed DDL remains APPLYING and readiness plus blind replay fail closed',function()use($root,&$proof): void{$db=isolatedDomainDb();$dir=$root.'/storage/f5-failed-ddl-'.bin2hex(random_bytes(6));mkdir($dir,0700);$file=$dir.'/001_failure.php';file_put_contents($file,"<?php return ['CREATE TABLE synthetic_partial(id INT PRIMARY KEY) ENGINE=InnoDB','INVALID SYNTHETIC DDL'];");try{$m=new Migrator($db,$dir);raises(PDOException::class,fn()=>$m->migrate());same('APPLYING',$db->execute('SELECT status FROM schema_migrations')->fetchColumn());same(1,(int)$db->execute("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='synthetic_partial'")->fetchColumn());raises(RuntimeException::class,fn()=>$m->assertReady());raises(RuntimeException::class,fn()=>$m->migrate());$proof['cases']['failed_ddl']=['status'=>'APPLYING','partial_ddl_retained'=>true,'runtime_and_replay_blocked'=>true,'recovery'=>'consistent isolated restore or reviewed forward-fix; no destructive down'];}finally{unlink($file);rmdir($dir);}});
test('F5-A migration checksum tamper blocks current schema',function()use($db,$root): void{$db->execute("UPDATE schema_migrations SET checksum=REPEAT('0',64) WHERE version='049_support_core.php'");try{raises(RuntimeException::class,fn()=>(new Migrator($db,$root.'/migrations'))->assertReady());raises(RuntimeException::class,fn()=>(new Migrator($db,$root.'/migrations'))->migrate());}finally{$db->execute("UPDATE schema_migrations SET checksum=? WHERE version='049_support_core.php'",[hash_file('sha256',$root.'/migrations/049_support_core.php')]);}});
$exit=executeTests(true);if($exit===0&&getenv('F5_EVIDENCE')==='1'){file_put_contents($root.'/docs/evidence/f5-a/migrations.json',json_encode($proof,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));}exit($exit);
